{"content":"import { defineConfig } from "vite";
import react from "@vitejs/plugin-react-swc";
import path from "path";
import { componentTagger } from "lovable-tagger";

// op-web owns :8080; vite dev uses :5173 and proxies REST + gRPC-Web.
const REST_TARGET = process.env.VITE_API_PROXY_TARGET || "http://127.0.0.1:8080";
const GRPC_TARGET = process.env.VITE_GRPC_PROXY_TARGET || "http://127.0.0.1:8090";

// https://vitejs.dev/config/
export default defineConfig(({ mode }) => ({
  base: "/",
  server: {
    host: "::",
    port: 5173,
    hmr: {
      overlay: false,
    },
    proxy: {
      "/api": {
        target: REST_TARGET,
        changeOrigin: true,
        secure: false,
      },
      // gRPC-Web services hosted by op-grpc-bridge
      "/operation.v1": {
        target: GRPC_TARGET,
        changeOrigin: true,
        secure: false,
      },
      "/operation.registry.v1": {
        target: GRPC_TARGET,
        changeOrigin: true,
        secure: false,
      },
      "/operation.mail.v1": {
        target: GRPC_TARGET,
        changeOrigin: true,
        secure: false,
      },
      "/operation.privacy.v1": {
        target: GRPC_TARGET,
        changeOrigin: true,
        secure: false,
      },
      "/operation.registration.v1": {
        target: GRPC_TARGET,
        changeOrigin: true,
        secure: false,
      },
      "/op.mcp.v1": {
        target: GRPC_TARGET,
        changeOrigin: true,
        secure: false,
      },
      "/grpc.reflection": {
        target: GRPC_TARGET,
        changeOrigin: true,
        secure: false,
      },
    },
  },
  plugins: [react(), mode === "development" && componentTagger()].filter(Boolean),
  resolve: {
    alias: {
      "@": path.resolve(__dirname, "./src"),
    },
  },
}));
"}

{"content":"import { useState, useCallback, useRef, useEffect } from "react";
import { useEventStore } from "@/stores/event-store";
import {
  stateSync, eventChainService,
  pluginService, componentRegistry,
} from "@/grpc/client";
import { pluginMethods } from "@/grpc/plugin-methods";
import { hostRuntime } from "@/grpc/host-runtime";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { ScrollArea } from "@/components/ui/scroll-area";
import { Collapsible, CollapsibleContent, CollapsibleTrigger } from "@/components/ui/collapsible";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import {
  Activity, AlertTriangle, CheckCircle2, ChevronDown, Loader2,
  Play, RefreshCw, Wifi, WifiOff, XCircle, Zap,
} from "lucide-react";
import { cn } from "@/lib/utils";

/* ── Types ─────────────────────────────────────────────────────────────── */

type ProbeStatus = "idle" | "running" | "ok" | "error";

interface ProbeResult {
  name: string;
  service: string;
  method: string;
  status: ProbeStatus;
  latencyMs: number | null;
  error: string | null;
  response: unknown;
  timestamp: number | null;
}

interface StreamProbe {
  name: string;
  service: string;
  method: string;
  status: ProbeStatus;
  messagesReceived: number;
  firstMessageMs: number | null;
  error: string | null;
  abort: (() => void) | null;
}

const INITIAL_UNARY_PROBES: ProbeResult[] = [
  { name: "Get State", service: "StateSync", method: "GetState", status: "idle", latencyMs: null, error: null, response: null, timestamp: null },
  { name: "List Plugins", service: "PluginService", method: "ListPlugins", status: "idle", latencyMs: null, error: null, response: null, timestamp: null },
  { name: "Get Events", service: "EventChainService", method: "GetEvents", status: "idle", latencyMs: null, error: null, response: null, timestamp: null },
  { name: "Verify Chain", service: "EventChainService", method: "VerifyChain", status: "idle", latencyMs: null, error: null, response: null, timestamp: null },
  { name: "List DBs (OVS)", service: "ovsdb_bridge", method: "list_dbs", status: "idle", latencyMs: null, error: null, response: null, timestamp: null },
  { name: "Bridge State", service: "rovs_commands", method: "list_bridges", status: "idle", latencyMs: null, error: null, response: null, timestamp: null },
  { name: "System Info", service: "host_runtime", method: "get_system_info", status: "idle", latencyMs: null, error: null, response: null, timestamp: null },
  { name: "List Services", service: "host_runtime", method: "list_services", status: "idle", latencyMs: null, error: null, response: null, timestamp: null },
  { name: "List Interfaces", service: "host_runtime", method: "list_interfaces", status: "idle", latencyMs: null, error: null, response: null, timestamp: null },
  { name: "NUMA Topology", service: "host_runtime", method: "get_numa_topology", status: "idle", latencyMs: null, error: null, response: null, timestamp: null },
  { name: "Sample Metrics", service: "host_runtime", method: "sample_metrics", status: "idle", latencyMs: null, error: null, response: null, timestamp: null },
  { name: "Discover Components", service: "ComponentRegistry", method: "Discover", status: "idle", latencyMs: null, error: null, response: null, timestamp: null },
];

const INITIAL_STREAM_PROBES: StreamProbe[] = [
  { name: "StateSync.Subscribe", service: "StateSync", method: "Subscribe", status: "idle", messagesReceived: 0, firstMessageMs: null, error: null, abort: null },
  { name: "EventChain.SubscribeEvents", service: "EventChainService", method: "SubscribeEvents", status: "idle", messagesReceived: 0, firstMessageMs: null, error: null, abort: null },
  { name: "ComponentRegistry.Watch", service: "ComponentRegistry", method: "Watch", status: "idle", messagesReceived: 0, firstMessageMs: null, error: null, abort: null },
];

/* ── Helpers ────────────────────────────────────────────────────────────── */

const statusIcon = (s: ProbeStatus) => {
  switch (s) {
    case "idle": return <Wifi className="h-4 w-4 text-muted-foreground" />;
    case "running": return <Loader2 className="h-4 w-4 text-primary animate-spin" />;
    case "ok": return <CheckCircle2 className="h-4 w-4 text-emerald-500" />;
    case "error": return <XCircle className="h-4 w-4 text-destructive" />;
  }
};

const statusBadge = (s: ProbeStatus, idle = false) => {
  const map: Record<ProbeStatus, string> = {
    idle: "secondary",
    running: "default",
    ok: "default",
    error: "destructive",
  };
  const label =
    s === "running" ? "Testing…" :
    s === "ok" && idle ? "CONNECTED · IDLE" :
    s.toUpperCase();
  return (
    <Badge variant={map[s] as any} className={cn(s === "ok" && "bg-emerald-500/20 text-emerald-400 border-emerald-500/30")}>
      {label}
    </Badge>
  );
};

/* ── Component ──────────────────────────────────────────────────────────── */

export default function GrpcDiagnosticsPage() {
  const { connected, lastError, eventCounts, latestState, latestStats } = useEventStore();
  const [unaryProbes, setUnaryProbes] = useState<ProbeResult[]>(INITIAL_UNARY_PROBES);
  const [streamProbes, setStreamProbes] = useState<StreamProbe[]>(INITIAL_STREAM_PROBES);
  const [runningAll, setRunningAll] = useState(false);
  const streamAbortsRef = useRef<Map<string, () => void>>(new Map());

  // Cleanup stream probes on unmount
  useEffect(() => {
    return () => {
      streamAbortsRef.current.forEach((abort) => { try { abort(); } catch {} });
    };
  }, []);

  /* ── Unary probe runner ──────────────────────────────────────────────── */

  const runUnaryProbe = useCallback(async (index: number) => {
    setUnaryProbes((prev) => prev.map((p, i) => i === index ? { ...p, status: "running", error: null, response: null } : p));
    const probe = INITIAL_UNARY_PROBES[index];
    const start = performance.now();
    try {
      let response: unknown;
      switch (`${probe.service}.${probe.method}`) {
        case "StateSync.GetState":
          response = await stateSync.getState({ pluginId: "", objectPath: "" });
          break;
        case "PluginService.ListPlugins":
          response = await pluginService.listPlugins();
          break;
        case "EventChainService.GetEvents":
          response = await eventChainService.getEvents({ limit: 5 });
          break;
        case "EventChainService.VerifyChain":
          response = await eventChainService.verifyChain({ fromEventId: "0", toEventId: "0" });
          break;
        case "ovsdb_bridge.list_dbs":
          // Native OVSDB JSON-RPC plugin (replaces deprecated D-Bus OvsdbMirror).
          response = await pluginMethods.callSubid("obs.network.ovsdb.dbs.list@v1", {});
          break;
        case "rovs_commands.list_bridges": {
          // Decomposed replacement for OvsdbMirror.GetBridgeState.
          const bridges = await pluginMethods.callSubid<Record<string, unknown>, Record<string, unknown>>(
            "obs.network.ovsdb.bridge.list@v1", {},
          );
          const names = (Array.isArray((bridges as any).bridges) ? (bridges as any).bridges : []) as string[];
          const ports = await Promise.all(
            names.map(async (bridgeName) => {
              try {
                return { bridge: bridgeName, ...(await pluginMethods.callSubid("obs.network.ovsdb.port.list@v1", { bridgeName })) };
              } catch (e) {
                return { bridge: bridgeName, error: (e as Error).message };
              }
            }),
          );
          response = { bridges, ports };
          break;
        }
        case "host_runtime.get_system_info":
          response = await hostRuntime.getSystemInfo();
          break;
        case "host_runtime.list_services":
          response = await hostRuntime.listServices();
          break;
        case "host_runtime.list_interfaces":
          response = await hostRuntime.listInterfaces();
          break;
        case "host_runtime.get_numa_topology":
          response = await hostRuntime.getNumaTopology();
          break;
        case "host_runtime.sample_metrics":
          response = await hostRuntime.sampleMetrics();
          break;
        case "ComponentRegistry.Discover":
          response = await componentRegistry.discover();
          break;
        default:
          throw new Error("Unknown probe");
      }
      const latency = Math.round(performance.now() - start);
      setUnaryProbes((prev) => prev.map((p, i) => i === index ? { ...p, status: "ok", latencyMs: latency, response, timestamp: Date.now() } : p));
    } catch (err) {
      const latency = Math.round(performance.now() - start);
      setUnaryProbes((prev) => prev.map((p, i) => i === index ? { ...p, status: "error", latencyMs: latency, error: (err as Error).message, timestamp: Date.now() } : p));
    }
  }, []);

  /* ── Stream probe runner ─────────────────────────────────────────────── */

  /**
   * If the stream opens cleanly but no first event arrives within the grace
   * period, treat it as connected/idle ("ok, waiting for events") rather than
   * leaving the probe spinning forever.
   */
  const STREAM_IDLE_GRACE_MS = 2500;

  const runStreamProbe = useCallback((index: number) => {
    const probe = INITIAL_STREAM_PROBES[index];
    const key = probe.name;

    // Abort existing
    const existing = streamAbortsRef.current.get(key);
    if (existing) { try { existing(); } catch {} }

    setStreamProbes((prev) => prev.map((p, i) => i === index ? { ...p, status: "running", messagesReceived: 0, firstMessageMs: null, error: null } : p));

    const start = performance.now();
    let gotFirst = false;
    let idleTimer: ReturnType<typeof setTimeout> | null = null;

    try {
      let result: { stream: ReadableStream<unknown>; abort: () => void };
      switch (key) {
        case "StateSync.Subscribe":
          result = stateSync.subscribe({ includeInitialState: true });
          break;
        case "EventChain.SubscribeEvents":
          result = eventChainService.subscribeEvents({ fromEventId: "0" });
          break;
        case "ComponentRegistry.Watch":
          result = componentRegistry.watch({ componentTypes: [], includeExisting: true });
          break;
        default:
          throw new Error("Unknown stream probe");
      }

      streamAbortsRef.current.set(key, result.abort);

      // Promote to "ok (idle)" after the grace period if nothing arrived.
      idleTimer = setTimeout(() => {
        if (!gotFirst) {
          setStreamProbes((prev) => prev.map((p, i) =>
