import type { ComponentType } from "react";
import { Shell } from "./components/shell";
import { NavItem } from "./components/nav";
import { PageHeader } from "./components/page-header";
import { Container, Grid, Card } from "./components/layout";
import { Kv, Text, Badge, Stat } from "./components/data";
import { PluginState, StateValue } from "./components/live";

export const registry: Record<string, ComponentType<any>> = {
  shell: Shell,
  navItem: NavItem,
  pageHeader: PageHeader,
  container: Container,
  grid: Grid,
  card: Card,
  kv: Kv,
  text: Text,
  badge: Badge,
  stat: Stat,
  pluginState: PluginState,
  stateValue: StateValue,
};

import type { ReactNode } from "react";

interface ShellProps {
  props: { navCollapsed?: boolean | null };
  slots?: { nav?: ReactNode; header?: ReactNode; content?: ReactNode };
  children?: ReactNode;
}

export function Shell({ props, slots }: ShellProps) {
  const collapsed = props.navCollapsed ?? false;
  return (
    <div className="flex h-screen overflow-hidden">
      <aside
        className={`${collapsed ? "w-14" : "w-56"} flex-shrink-0 border-r border-neutral-800 bg-neutral-900 flex flex-col transition-all`}
      >
        <div className="p-3 text-sm font-bold tracking-tight text-neutral-300 border-b border-neutral-800">
          {collapsed ? "3t" : "3tched"}
        </div>
        <nav className="flex-1 overflow-y-auto py-2">{slots?.nav}</nav>
      </aside>
      <main className="flex-1 flex flex-col overflow-hidden">
        {slots?.header && (
          <header className="border-b border-neutral-800 px-6 py-3">
            {slots.header}
          </header>
        )}
        <div className="flex-1 overflow-y-auto p-6">{slots?.content ?? children}</div>
      </main>
    </div>
  );
}

const children = null;

interface NavItemProps {
  props: {
    label: string;
    route: string;
    icon?: string | null;
    active?: boolean | null;
  };
  emit?: (event: string) => void;
}

export function NavItem({ props, emit }: NavItemProps) {
  const active = props.active ?? false;
  return (
    <button
      onClick={() => emit?.("press")}
      className={`w-full text-left px-3 py-1.5 text-sm rounded-md mx-1 ${
        active
          ? "bg-neutral-700 text-neutral-100 font-medium"
          : "text-neutral-400 hover:bg-neutral-800 hover:text-neutral-200"
      }`}
    >
      {props.label}
    </button>
  );
}

interface PageHeaderProps {
  props: {
    title: string;
    subtitle?: string | null;
  };
}

export function PageHeader({ props }: PageHeaderProps) {
  return (
    <div>
      <h1 className="text-xl font-semibold text-neutral-100">{props.title}</h1>
      {props.subtitle && (
        <p className="text-sm text-neutral-400 mt-0.5">{props.subtitle}</p>
      )}
    </div>
  );
}

import type { ReactNode } from "react";

interface ContainerProps {
  props: { className?: string | null };
  children?: ReactNode;
}

export function Container({ props, children }: ContainerProps) {
  return <div className={props.className ?? "flex flex-col gap-4"}>{children}</div>;
}

interface GridProps {
  props: { cols: number; gap?: number | null; className?: string | null };
  children?: ReactNode;
}

export function Grid({ props, children }: GridProps) {
  const style = {
    display: "grid",
    gridTemplateColumns: `repeat(${props.cols}, minmax(0, 1fr))`,
    gap: `${props.gap ?? 4}px`,
  };
  return (
    <div style={style} className={props.className ?? ""}>
      {children}
    </div>
  );
}

interface CardProps {
  props: { title?: string | null; className?: string | null };
  children?: ReactNode;
}

export function Card({ props, children }: CardProps) {
  return (
    <div className={`rounded-lg border border-neutral-800 bg-neutral-900/50 p-4 ${props.className ?? ""}`}>
      {props.title && (
        <h3 className="text-sm font-medium text-neutral-300 mb-3">{props.title}</h3>
      )}
      {children}
    </div>
  );
}

interface KvProps {
  props: { label: string; value: unknown; kind?: string | null };
}

export function Kv({ props }: KvProps) {
  const display =
    props.value === null || props.value === undefined
      ? "—"
      : typeof props.value === "object"
        ? JSON.stringify(props.value)
        : String(props.value);

  return (
    <div className="flex items-baseline justify-between py-1 text-sm">
      <span className="text-neutral-400">{props.label}</span>
      <span className="text-neutral-100 font-mono text-xs">{display}</span>
    </div>
  );
}

interface TextProps {
  props: { text: string; className?: string | null };
}

export function Text({ props }: TextProps) {
  return <p className={props.className ?? "text-sm text-neutral-300"}>{props.text}</p>;
}

interface BadgeProps {
  props: { label: string; tone?: "default" | "ok" | "warn" | "danger" | "info" | null };
}

const TONE_CLASSES: Record<string, string> = {
  default: "bg-neutral-800 text-neutral-300",
  ok: "bg-emerald-900/60 text-emerald-300",
  warn: "bg-amber-900/60 text-amber-300",
  danger: "bg-red-900/60 text-red-300",
  info: "bg-sky-900/60 text-sky-300",
};

export function Badge({ props }: BadgeProps) {
  const cls = TONE_CLASSES[props.tone ?? "default"] ?? TONE_CLASSES.default;
  return (
    <span className={`inline-block px-2 py-0.5 rounded text-xs font-medium ${cls}`}>
      {props.label}
    </span>
  );
}

interface StatProps {
  props: {
    label: string;
    value: string;
    unit?: string | null;
    trend?: "up" | "down" | "flat" | null;
  };
}

const TREND_ICON: Record<string, string> = { up: "\u2191", down: "\u2193", flat: "\u2192" };

export function Stat({ props }: StatProps) {
  return (
    <div className="flex flex-col gap-0.5">
      <span className="text-xs text-neutral-500">{props.label}</span>
      <span className="text-lg font-semibold text-neutral-100">
        {props.value}
        {props.unit && <span className="text-sm text-neutral-400 ml-1">{props.unit}</span>}
        {props.trend && (
          <span className="text-sm ml-1">{TREND_ICON[props.trend] ?? ""}</span>
        )}
      </span>
    </div>
  );
}

import type { ReactNode } from "react";
import { useStateStore } from "@/store/state-store";

interface PluginStateProps {
  props: { pluginId: string };
  children?: ReactNode;
}

export function PluginState({ props, children }: PluginStateProps) {
  const state = useStateStore((s) => s.plugins[props.pluginId]);
  if (!state) {
    return (
      <div className="text-xs text-neutral-500 italic">
        waiting for {props.pluginId}...
      </div>
    );
  }
  return <>{children}</>;
}

interface StateValueProps {
  props: {
    path: string;
    label?: string | null;
    format?: "raw" | "json" | "bytes" | "duration" | null;
  };
}

export function StateValue({ props }: StateValueProps) {
  const value = useStateStore((s) => {
    const parts = props.path.split(".");
    let current: unknown = s.plugins;
    for (const part of parts) {
      if (current === null || current === undefined || typeof current !== "object") return undefined;
      current = (current as Record<string, unknown>)[part];
    }
    return current;
  });

  const display =
    value === null || value === undefined
      ? "—"
      : props.format === "json"
        ? JSON.stringify(value, null, 2)
        : props.format === "bytes" && typeof value === "number"
          ? formatBytes(value)
          : String(value);

  return (
    <div className="flex items-baseline justify-between py-1 text-sm">
      {props.label && <span className="text-neutral-400">{props.label}</span>}
      <span className="text-neutral-100 font-mono text-xs whitespace-pre-wrap">{display}</span>
    </div>
  );
}

function formatBytes(bytes: number): string {
  if (bytes < 1024) return `${bytes} B`;
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
  if (bytes < 1024 * 1024 * 1024) return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
  return `${(bytes / (1024 * 1024 * 1024)).toFixed(2)} GB`;
}

/**
 * Binary gRPC-Web transport. Sends application/grpc-web+proto frames,
 * parses data frames (0x00) and trailers (0x80) from the response.
 */

const CONTENT_TYPE = "application/grpc-web+proto";

function getBaseUrl(): string {
  if (typeof window !== "undefined" && window.location?.origin) {
    return window.location.origin;
  }
  return "";
}

function identityHeaders(): Record<string, string> {
  const headers: Record<string, string> = { "x-grpc-web": "1" };
  // Identity is resolved from the sled endpoint on first load
  const stored = sessionStorage.getItem("opdbus-identity");
  if (stored) {
    try {
      const { hashed_footprint, trace_id } = JSON.parse(stored);
      if (hashed_footprint) headers["x-ghostbridge-footprint"] = hashed_footprint;
      if (trace_id) headers["x-ghostbridge-trace-id"] = trace_id;
    } catch { /* ignore */ }
  }
  return headers;
}

function frameMessage(payload: Uint8Array): Uint8Array {
  const frame = new Uint8Array(5 + payload.length);
  frame[0] = 0x00;
  new DataView(frame.buffer).setUint32(1, payload.length, false);
  frame.set(payload, 5);
  return frame;
}

export interface StreamHandle<T> {
  stream: ReadableStream<T>;
  abort: () => void;
}

/**
 * Open a server-streaming gRPC-Web call. Returns a ReadableStream of raw
 * Uint8Array data frame payloads (caller decodes protobuf).
 */
export function grpcServerStream(
  service: string,
  method: string,
  requestBytes: Uint8Array = new Uint8Array(0),
): StreamHandle<Uint8Array> {
  const controller = new AbortController();
  const url = `${getBaseUrl()}/${service}/${method}`;
  const frame = frameMessage(requestBytes);

  const responsePromise = fetch(url, {
    method: "POST",
    headers: { "Content-Type": CONTENT_TYPE, Accept: CONTENT_TYPE, ...identityHeaders() },
    body: frame,
    signal: controller.signal,
  });

  const stream = new ReadableStream<Uint8Array>({
    async start(ctrl) {
      try {
        const res = await responsePromise;
        if (!res.ok || !res.body) {
          ctrl.error(new Error(`gRPC stream failed: HTTP ${res.status}`));
          return;
        }
        const reader = res.body.getReader();
        let pending = new Uint8Array(0);

        while (true) {
          const { done, value } = await reader.read();
          if (done) break;

          const merged = new Uint8Array(pending.length + value.length);
          merged.set(pending);
          merged.set(value, pending.length);
          pending = merged;

          while (pending.length >= 5) {
            const flags = pending[0]!;
            const len = new DataView(pending.buffer, pending.byteOffset + 1, 4).getUint32(0, false);
            if (pending.length < 5 + len) break;
            const payload = pending.slice(5, 5 + len);

            if (flags & 0x80) {
              // Trailers — check for error
              const text = new TextDecoder().decode(payload);
              const trailers = new Map<string, string>();
              for (const line of text.split(/\r?\n/)) {
                const idx = line.indexOf(":");
                if (idx > 0) trailers.set(line.slice(0, idx).trim().toLowerCase(), line.slice(idx + 1).trim());
              }
              const st = trailers.get("grpc-status");
              if (st && st !== "0") {
                ctrl.error(new Error(`gRPC error ${st}: ${trailers.get("grpc-message") ?? ""}`));
                return;
              }
            } else {
              ctrl.enqueue(payload);
            }
            pending = pending.slice(5 + len);
          }
        }
        ctrl.close();
      } catch (err) {
        if ((err as Error).name !== "AbortError") ctrl.error(err);
      }
    },
  });

  return { stream, abort: () => controller.abort() };
}

/**
 * Resolve identity from the sled endpoint and store in sessionStorage.
 */
export async function resolveIdentity(): Promise<boolean> {
  try {
    const res = await fetch("/api/identity/sled");
    if (!res.ok) return false;
    const body = await res.json();
    if (!body.is_valid || !body.hashed_footprint || !body.trace_id) return false;
    sessionStorage.setItem("opdbus-identity", JSON.stringify({
      hashed_footprint: body.hashed_footprint,
      trace_id: body.trace_id,
    }));
    return true;
  } catch {
    return false;
  }
}

import { create } from "zustand";

export interface StateStore {
  connected: boolean;
  plugins: Record<string, Record<string, unknown>>;
  /** Set connection status */
  setConnected: (connected: boolean) => void;
  /** Apply a state update for a plugin (full or member-level) */
  applyUpdate: (pluginId: string, memberName: string | undefined, value: unknown) => void;
  /** Get a nested value by dot-path */
  getValue: (path: string) => unknown;
}

export const useStateStore = create<StateStore>((set, get) => ({
  connected: false,
  plugins: {},

  setConnected: (connected) => set({ connected }),

  applyUpdate: (pluginId, memberName, value) =>
    set((state) => {
      const plugin = state.plugins[pluginId] ?? {};
      if (!memberName) {
        // Full plugin state replace
        const newState = value && typeof value === "object" && !Array.isArray(value)
          ? (value as Record<string, unknown>)
          : { _value: value };
        return { plugins: { ...state.plugins, [pluginId]: newState } };
      }
      // Member-level update
      return {
        plugins: {
          ...state.plugins,
          [pluginId]: { ...plugin, [memberName]: value },
        },
      };
    }),

  getValue: (path) => {
    const parts = path.split(".");
    let current: unknown = get().plugins;
    for (const part of parts) {
      if (current === null || current === undefined || typeof current !== "object") return undefined;
      current = (current as Record<string, unknown>)[part];
    }
    return current;
  },
}));

import { useEffect, useRef } from "react";
import { grpcServerStream, resolveIdentity } from "./grpc-transport";
import { useStateStore } from "@/store/state-store";
import { decodeStateChange } from "./decode";

/**
 * Connects to the StateSync.Subscribe gRPC server stream and pushes
 * frames into the zustand state store. Reconnects on disconnect.
 */
export function useEventStream() {
  const setConnected = useStateStore((s) => s.setConnected);
  const applyUpdate = useStateStore((s) => s.applyUpdate);
  const abortRef = useRef<(() => void) | null>(null);

  useEffect(() => {
    let cancelled = false;

    async function connect() {
      // Resolve identity before opening the stream
      await resolveIdentity();

      if (cancelled) return;

      // Subscribe request: empty = all plugins, include initial state
      // Protobuf encoding of SubscribeRequest { include_initial_state: true }
      // field 4, varint 1 → [0x20, 0x01]
      const subscribePayload = new Uint8Array([0x20, 0x01]);

      const { stream, abort } = grpcServerStream(
        "operation.v1.StateSync",
        "Subscribe",
        subscribePayload,
      );
      abortRef.current = abort;
      setConnected(true);

      try {
        const reader = stream.getReader();
        while (true) {
          const { done, value } = await reader.read();
          if (done || cancelled) break;

          const change = decodeStateChange(value);
          if (change && change.pluginId && change.newValue !== undefined) {
            applyUpdate(change.pluginId, change.memberName, change.newValue);
          }
        }
      } catch (err) {
        if (!cancelled) {
          console.warn("[event-stream] disconnected:", err);
        }
      }

      setConnected(false);
      abortRef.current = null;

      // Reconnect after 3s
      if (!cancelled) {
        setTimeout(connect, 3000);
      }
    }

    connect();

    return () => {
      cancelled = true;
      abortRef.current?.();
    };
  }, [setConnected, applyUpdate]);
}

/**
 * Minimal protobuf decoder for StateChange messages.
 *
 * StateChange wire format (from operation.proto):
 *   1: string plugin_id
 *   2: string member_name
 *   3: ChangeType change_type (enum/varint)
 *   5: google.protobuf.Value new_value
 *   8: string schema_hash
 *  13: StateFrameKind frame_kind (enum/varint)
 *
 * We only need plugin_id, member_name, and new_value for the state store.
 * google.protobuf.Value is decoded into native JS values.
 */

export interface DecodedStateChange {
  pluginId: string;
  memberName: string | undefined;
  newValue: unknown;
  frameKind: number;
}

export function decodeStateChange(buf: Uint8Array): DecodedStateChange | null {
  try {
    const reader = new ProtoReader(buf);
    let pluginId = "";
    let memberName: string | undefined;
    let newValue: unknown;
    let frameKind = 0;

    while (reader.hasMore()) {
      const tag = reader.readTag();
      const fieldNumber = tag >>> 3;
      const wireType = tag & 0x07;

      switch (fieldNumber) {
        case 1: pluginId = reader.readString(); break;
        case 2: memberName = reader.readString() || undefined; break;
        case 3: frameKind = reader.readVarint(); break; // ChangeType
        case 5: newValue = decodeValue(reader.readBytes()); break;
        case 13: frameKind = reader.readVarint(); break; // StateFrameKind
        default: reader.skip(wireType); break;
      }
    }

    // frameKind 3 = HEARTBEAT — skip
    if (frameKind === 3) return null;
    if (!pluginId) return null;

    return { pluginId, memberName, newValue, frameKind };
  } catch {
    return null;
  }
}

/** Decode google.protobuf.Value → JS value */
function decodeValue(buf: Uint8Array): unknown {
  if (buf.length === 0) return null;
  const reader = new ProtoReader(buf);
  while (reader.hasMore()) {
    const tag = reader.readTag();
    const fieldNumber = tag >>> 3;
    switch (fieldNumber) {
      case 1: return null; // null_value
      case 2: return reader.readDouble(); // number_value
      case 3: return reader.readString(); // string_value
      case 4: return reader.readVarint() !== 0; // bool_value
      case 5: return decodeStruct(reader.readBytes()); // struct_value
      case 6: return decodeListValue(reader.readBytes()); // list_value
      default: reader.skip(tag & 0x07); break;
    }
  }
  return null;
}

/** Decode google.protobuf.Struct → Record<string, unknown> */
function decodeStruct(buf: Uint8Array): Record<string, unknown> {
  const result: Record<string, unknown> = {};
  const reader = new ProtoReader(buf);
  while (reader.hasMore()) {
    const tag = reader.readTag();
    if ((tag >>> 3) === 1) {
      // fields: map<string, Value> — each entry is a length-delimited sub-message
      const entryBuf = reader.readBytes();
      const entryReader = new ProtoReader(entryBuf);
      let key = "";
      let value: unknown = null;
      while (entryReader.hasMore()) {
        const entryTag = entryReader.readTag();
        if ((entryTag >>> 3) === 1) key = entryReader.readString();
        else if ((entryTag >>> 3) === 2) value = decodeValue(entryReader.readBytes());
        else entryReader.skip(entryTag & 0x07);
      }
      if (key) result[key] = value;
    } else {
      reader.skip(tag & 0x07);
    }
  }
  return result;
}

/** Decode google.protobuf.ListValue → unknown[] */
function decodeListValue(buf: Uint8Array): unknown[] {
  const result: unknown[] = [];
  const reader = new ProtoReader(buf);
  while (reader.hasMore()) {
    const tag = reader.readTag();
    if ((tag >>> 3) === 1) {
      result.push(decodeValue(reader.readBytes()));
    } else {
      reader.skip(tag & 0x07);
    }
  }
  return result;
}

/** Minimal protobuf wire-format reader */
class ProtoReader {
  private pos = 0;
  constructor(private buf: Uint8Array) {}

  hasMore(): boolean { return this.pos < this.buf.length; }

  readVarint(): number {
    let result = 0;
    let shift = 0;
    while (this.pos < this.buf.length) {
      const byte = this.buf[this.pos++]!;
      result |= (byte & 0x7f) << shift;
      if ((byte & 0x80) === 0) return result >>> 0;
      shift += 7;
    }
    return result >>> 0;
  }

  readTag(): number { return this.readVarint(); }

  readBytes(): Uint8Array {
    const len = this.readVarint();
    const bytes = this.buf.slice(this.pos, this.pos + len);
    this.pos += len;
    return bytes;
  }

  readString(): string {
    return new TextDecoder().decode(this.readBytes());
  }

  readDouble(): number {
    const bytes = this.buf.slice(this.pos, this.pos + 8);
    this.pos += 8;
    return new DataView(bytes.buffer, bytes.byteOffset, 8).getFloat64(0, true);
  }

  skip(wireType: number): void {
    switch (wireType) {
      case 0: this.readVarint(); break;
      case 1: this.pos += 8; break;
      case 2: this.pos += this.readVarint(); break;
      case 5: this.pos += 4; break;
      default: break;
    }
  }
}

