}

interface PageHeaderRenderProps {
  element: { props: { title: string; subtitle?: string | null } };
}

export function PageHeader({ element }: PageHeaderRenderProps) {
  const { title, subtitle } = element.props;
  return (
    <div>
      <h1 className="text-xl font-semibold text-neutral-100">{title}</h1>
      {subtitle && <p className="text-sm text-neutral-400 mt-0.5">{subtitle}</p>}
    </div>
  );
}

import type { ReactNode } from "react";

interface ContainerRenderProps {
  element: { props: { className?: string | null } };
  children?: ReactNode;
}

export function Container({ element, children }: ContainerRenderProps) {
  return <div className={element.props?.className ?? "flex flex-col gap-4"}>{children}</div>;
}

interface GridRenderProps {
  element: { props: { cols: number; gap?: number | null; className?: string | null } };
  children?: ReactNode;
}

export function Grid({ element, children }: GridRenderProps) {
  const { cols, gap, className } = element.props;
  const style = {
    display: "grid",
    gridTemplateColumns: `repeat(${cols}, minmax(0, 1fr))`,
    gap: `${gap ?? 16}px`,
  };
  return (
    <div style={style} className={className ?? ""}>
      {children}
    </div>
  );
}

interface CardRenderProps {
  element: { props: { title?: string | null; className?: string | null } };
  children?: ReactNode;
}

export function Card({ element, children }: CardRenderProps) {
  const { title, className } = element.props;
  return (
    <div className={`rounded-lg border border-neutral-800 bg-neutral-900/50 p-4 ${className ?? ""}`}>
      {title && <h3 className="text-sm font-medium text-neutral-300 mb-3">{title}</h3>}
      {children}
    </div>
  );
}

interface KvRenderProps {
  element: { props: { label: string; value: unknown; kind?: string | null } };
}

export function Kv({ element }: KvRenderProps) {
  const { label, value } = element.props;
  const display =
    value === null || value === undefined
      ? "\u2014"
      : typeof value === "object"
        ? JSON.stringify(value)
        : String(value);

  return (
    <div className="flex items-baseline justify-between py-1 text-sm">
      <span className="text-neutral-400">{label}</span>
      <span className="text-neutral-100 font-mono text-xs">{display}</span>
    </div>
  );
}

interface TextRenderProps {
  element: { props: { text: string; className?: string | null } };
}

export function Text({ element }: TextRenderProps) {
  return <p className={element.props.className ?? "text-sm text-neutral-300"}>{element.props.text}</p>;
}

interface BadgeRenderProps {
  element: { props: { label: string; tone?: "default" | "ok" | "warn" | "danger" | "info" | null } };
}

const TONE_CLASSES: Record<string, string> = {
  default: "bg-neutral-800 text-neutral-300",
  ok: "bg-emerald-900/60 text-emerald-300",
  warn: "bg-amber-900/60 text-amber-300",
  danger: "bg-red-900/60 text-red-300",
  info: "bg-sky-900/60 text-sky-300",
};

export function Badge({ element }: BadgeRenderProps) {
  const { label, tone } = element.props;
  const cls = TONE_CLASSES[tone ?? "default"] ?? TONE_CLASSES.default;
  return (
    <span className={`inline-block px-2 py-0.5 rounded text-xs font-medium ${cls}`}>
      {label}
    </span>
  );
}

interface StatRenderProps {
  element: {
    props: {
      label: string;
      value: string;
      unit?: string | null;
      trend?: "up" | "down" | "flat" | null;
    };
  };
}

const TREND_ICON: Record<string, string> = { up: "\u2191", down: "\u2193", flat: "\u2192" };

export function Stat({ element }: StatRenderProps) {
  const { label, value, unit, trend } = element.props;
  return (
    <div className="flex flex-col gap-0.5">
      <span className="text-xs text-neutral-500">{label}</span>
      <span className="text-lg font-semibold text-neutral-100">
        {value}
        {unit && <span className="text-sm text-neutral-400 ml-1">{unit}</span>}
        {trend && <span className="text-sm ml-1">{TREND_ICON[trend] ?? ""}</span>}
      </span>
    </div>
  );
}

import type { ReactNode } from "react";
import { useStateStore } from "@/store/state-store";

interface PluginStateRenderProps {
  element: { props: { pluginId: string } };
  children?: ReactNode;
}

export function PluginState({ element, children }: PluginStateRenderProps) {
  const state = useStateStore((s) => s.plugins[element.props.pluginId]);
  if (!state) {
    return (
      <div className="text-xs text-neutral-500 italic">
        waiting for {element.props.pluginId}...
      </div>
    );
  }
  return <>{children}</>;
}

interface StateValueRenderProps {
  element: {
    props: {
      path: string;
      label?: string | null;
      format?: "raw" | "json" | "bytes" | "duration" | null;
    };
  };
}

export function StateValue({ element }: StateValueRenderProps) {
  const { path, label, format } = element.props;
  const value = useStateStore((s) => {
    const parts = path.split(".");
    let current: unknown = s.plugins;
    for (const part of parts) {
      if (current === null || current === undefined || typeof current !== "object") return undefined;
      current = (current as Record<string, unknown>)[part];
    }
    return current;
  });

  const display =
    value === null || value === undefined
      ? "\u2014"
      : format === "json"
        ? JSON.stringify(value, null, 2)
        : format === "bytes" && typeof value === "number"
          ? formatBytes(value)
          : String(value);

  return (
    <div className="flex items-baseline justify-between py-1 text-sm">
      {label && <span className="text-neutral-400">{label}</span>}
      <span className="text-neutral-100 font-mono text-xs whitespace-pre-wrap">{display}</span>
    </div>
  );
}

function formatBytes(bytes: number): string {
  if (bytes < 1024) return `${bytes} B`;
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
  if (bytes < 1024 * 1024 * 1024) return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
  return `${(bytes / (1024 * 1024 * 1024)).toFixed(2)} GB`;
}

